import{_ as t,o as e,c as s,a6 as n}from"./chunks/framework.B_q3ZJNF.js";const h=JSON.parse('{"title":"三块芯片的合奏:NES 硬件全景与时钟同步","description":"","frontmatter":{"title":"三块芯片的合奏:NES 硬件全景与时钟同步"},"headers":[],"relativePath":"nes-emulator-course/01-nes-overview.md","filePath":"nes-emulator-course/docs/01-nes-overview.md"}'),l={name:"nes-emulator-course/01-nes-overview.md"};function p(r,a,i,d,o,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="三块芯片的合奏-nes-硬件全景与时钟同步" tabindex="-1">三块芯片的合奏:NES 硬件全景与时钟同步 <a class="header-anchor" href="#三块芯片的合奏-nes-硬件全景与时钟同步" aria-label="Permalink to &quot;三块芯片的合奏:NES 硬件全景与时钟同步&quot;">​</a></h1><p>动手写模拟器的第一晚,大多数人会踩同一个坑:抄半张 6502 指令表,搭一个执行循环,让 CPU 全速跑——每秒几百万条指令,风驰电掣。然后盯着一片黑的屏幕发呆。没有报错,没有崩溃,一切看起来都「正常」,只是画面永远不出现。</p><p>问题不在指令表抄没抄对,而在于你模拟的本来就不是一个「CPU」,而是一台由多块芯片协作的机器:CPU 只负责算,画面由另一块芯片按自己的节拍生成,而两者的时间必须严格对齐——CPU 每走一个周期,图形芯片要走三个点。缺了这个对齐,游戏里「等垂直消隐再上传画面数据」的代码永远等不到时机,于是什么都画不出来。</p><p>这一章不写代码。先把整台机器的地图装进脑子,后面每一章都是在这张地图上施工。</p><h2 id="真机上是三块芯片在合奏" tabindex="-1">真机上是三块芯片在合奏 <a class="header-anchor" href="#真机上是三块芯片在合奏" aria-label="Permalink to &quot;真机上是三块芯片在合奏&quot;">​</a></h2><p>把一台 NES 拆开,和模拟器有关的是三块芯片和一张卡带,像一支四人乐队:</p><ul><li><strong>中央处理器(CPU)</strong>:核心是一颗 6502(任天堂定制版叫 2A03),8 位,主频约 1.79MHz。它执行卡带里的程序,靠十几种寻址模式取操作数,是唯一「会思考」的角色——主唱。</li><li><strong>图形处理器(PPU,2C02)</strong>:独立于 CPU 的绘图芯片,频率是 CPU 的三倍。它不执行程序,只按固定节拍把显存内容变成电视信号——吉他手,不 听 主唱的,只听节拍器。</li><li><strong>声音处理器(APU)</strong>:和 CPU 封装在同一颗 2A03 里,负责方波、三角波和噪声。本课程主线不实现它,但会留好接口与路线。</li><li><strong>卡带</strong>:它不是外设,而是总线上的第一等公民。卡带里有两块 ROM——PRG-ROM 存程序(给 CPU 读),CHR-ROM 存图形数据(给 PPU 读),板子上还有映射器(mapper)电路,决定这两块 ROM 如何出现在地址空间里。</li></ul><p>最后一个角色是节拍器:一颗约 21.47MHz 的主晶振,经分频后驱动所有芯片。<strong>整台机器的秘密全在「谁在什么节拍上做什么」</strong>。</p><h2 id="两条总线-cpu-总线与-ppu-显存" tabindex="-1">两条总线:CPU 总线与 PPU 显存 <a class="header-anchor" href="#两条总线-cpu-总线与-ppu-显存" aria-label="Permalink to &quot;两条总线:CPU 总线与 PPU 显存&quot;">​</a></h2><p>CPU 眼中只有一个 64KB 地址空间,但这个空间被硬件划分给了不同设备:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU 总线(16 位地址空间 $0000-$FFFF)</span></span>
<span class="line"><span>┌──────────┬─────────────┬───────────────┬─────────────────┐</span></span>
<span class="line"><span>│ $0000    │ $2000       │ $4000         │ $4020           │</span></span>
<span class="line"><span>│ 机器内部  │ PPU 的      │ APU 与手柄    │ 卡带窗口        │</span></span>
<span class="line"><span>│ RAM 2KB  │ 8 个寄存器   │ 的寄存器      │ (PRG-ROM 在此) │</span></span>
<span class="line"><span>└──────────┴─────────────┴───────────────┴─────────────────┘</span></span></code></pre></div><p>注意第一栏:机器内部 RAM 只有 2KB,却占着 8KB 的地址段——同一块 RAM 在 $0000-$1FFF 里重复出现四次,这就是镜像(mirroring)。同样的把戏在 PPU 寄存器段($2000-$3FFF 每 8 字节重复一次)和显存里都存在。模拟器如果只认「第一个」地址,真机程序写到镜像地址的数据就会凭空丢失——这是新手模拟器最常见的一类「无声无息的 bug」。</p><p>PPU 还有自己的第二条总线,连接显存:命名表(nametable,记录「屏幕每个 8×8 格子画哪个瓦片」)、图块表(pattern table,瓦片的位图库)、调色板(palette,把像素值映射成 64 种系统色之一)。CPU 不能直接访问这条总线,只能通过 $2006/$2007 两个寄存器一点一点地读写——这个「绕道」是很多真机程序的写法根源。显存之外还有一块 256 字节的精灵内存(OAM),记录 64 个精灵的位置与图案;PPU 画图时把瓦片数据装进移位寄存器,再一个像素一个像素地吐到屏幕上。</p><h2 id="_3-1-的时钟-与一帧的形状" tabindex="-1">3:1 的时钟,与一帧的形状 <a class="header-anchor" href="#_3-1-的时钟-与一帧的形状" aria-label="Permalink to &quot;3:1 的时钟,与一帧的形状&quot;">​</a></h2><p>CPU 和 PPU 各自跑在自己的频率上,但锁定为 3:1——CPU 一个周期里,PPU 走三个点(dot)。PPU 用「扫描线与点」组成的二维坐标来计时:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一帧 = 262 条扫描线 × 341 点 = 89342 个 PPU 周期(约 60Hz)</span></span>
<span class="line"><span>├─ 扫描线 0-239:可见区,每线画出 256 个像素</span></span>
<span class="line"><span>├─ 扫描线 240:后渲染,歇一口气</span></span>
<span class="line"><span>├─ 扫描线 241-260:垂直消隐(VBlank),不画图,显存开放写入</span></span>
<span class="line"><span>│    └─ 进入时 PPU 拉起不可屏蔽中断(NMI),通知 CPU「现在可以上传了」</span></span>
<span class="line"><span>└─ 扫描线 261:预渲染,为下一帧重置内部状态</span></span></code></pre></div><p>游戏的主循环几乎都长一个样:垂直消隐一开始,PPU 就拉起不可屏蔽中断(NMI);游戏在中断处理例程里趁这段时间更新显存,回到主循环算游戏逻辑,等下一次 NMI。所以模拟器只要把「CPU 执行指令耗掉 N 个周期 → PPU 前进 3N 个点 → 到点触发 NMI」这条链对齐,画面自己就会出来。</p><h2 id="模拟器怎么切模块" tabindex="-1">模拟器怎么切模块 <a class="header-anchor" href="#模拟器怎么切模块" aria-label="Permalink to &quot;模拟器怎么切模块&quot;">​</a></h2><p>按硬件边界切,代码就不会拧成一团乱麻。本课程的伴生实验场最终长这样:</p><table tabindex="0"><thead><tr><th>模块</th><th>对应硬件</th><th>职责</th></tr></thead><tbody><tr><td><code>ines.ts</code></td><td>卡带的外壳</td><td>把 .nes 文件(iNES 格式)拆成 PRG、CHR、映射器号、镜像模式</td></tr><tr><td><code>cpu.ts</code> / <code>opcodes.ts</code></td><td>2A03 的 6502 核心</td><td>寄存器、取指执行、全部官方指令与周期数</td></tr><tr><td><code>ppu.ts</code></td><td>2C02</td><td>寄存器、显存、背景与精灵渲染、帧时序</td></tr><tr><td><code>bus.ts</code></td><td>主板上的连线</td><td>地址路由与镜像,把上面三者连成整体</td></tr><tr><td><code>controller.ts</code></td><td>手柄接口</td><td>把按键变成 CPU 可读取的串行数据</td></tr><tr><td><code>nes.ts</code></td><td>整机外壳</td><td>时钟同步主循环:<code>runFrame()</code> 跑出一帧</td></tr></tbody></table><p>推进策略采用指令级追赶(catch-up):CPU 每执行一条指令,返回它消耗的周期数,主循环立刻让 PPU 补走三倍的点。这是「能正确跑起来」与「工程量可控」之间的最佳平衡点;更精细的逐周期模拟、更复杂的映射器,留到最后一章的精度阶梯再谈。</p><h2 id="读完本章你该能回答" tabindex="-1">读完本章你该能回答 <a class="header-anchor" href="#读完本章你该能回答" aria-label="Permalink to &quot;读完本章你该能回答&quot;">​</a></h2><ol><li>为什么 CPU 跑得再快,没有时钟同步画面就永远是黑的?</li><li>卡带上的 PRG-ROM 和 CHR-ROM 分别被谁读?通过哪条总线?</li><li>一帧有多少个 PPU 周期?VBlank 在哪几条扫描线,为什么游戏都抢在这段时间写显存?</li><li>NES 上有哪些「同一个东西出现在多个地址」的镜像?</li></ol><p>答不上来的,回到对应小节再读一遍——这四个问题是后面十一章的地基。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>NES 是三块芯片加一张卡带的总线合奏:CPU 执行程序,PPU 按三倍节拍画面,卡带是总线上的普通设备;时间以「一帧 262 线 × 341 点」计量,游戏的呼吸节奏由 VBlank 与 NMI 驱动。模拟器的模块边界就画在硬件边界上,推进用指令级追赶。接下来,先从把一张卡带拆开开始。</p><h3 id="章末地图" tabindex="-1">章末地图 <a class="header-anchor" href="#章末地图" aria-label="Permalink to &quot;章末地图&quot;">​</a></h3><ul><li><a href="./02-ines-cartridge.html">拆开一张卡带:iNES 格式</a>——地图里的卡带,变成数据结构</li><li><a href="./03-cpu-core.html">6502 最小核心</a>——主唱登场</li><li><a href="./06-ppu-bus-registers.html">PPU 寄存器与地址镜像</a>——总线图的中间两栏</li><li><a href="./09-frame-timing.html">帧时序:NMI 与主循环</a>——把 3:1 时钟焊成 runFrame</li></ul>`,28)])])}const u=t(l,[["render",p]]);export{h as __pageData,u as default};
